import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"LinkAction","description":"","frontmatter":{},"headers":[],"relativePath":"components/link-action.md","filePath":"components/link-action.md"}'),n={name:"components/link-action.md"};function d(r,t,s,c,h,l){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="linkaction" tabindex="-1">LinkAction <a class="header-anchor" href="#linkaction" aria-label="Permalink to &quot;LinkAction&quot;">​</a></h1><p>LinkAction is an action that is text only.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a light action that does not call for a control with a line, such as &quot;Add a description&quot; or &quot;Show all&quot;, also inside a sentence. An action that opens a modal or changes the screen is a <a href="./button">Button</a>. With <code>href</code> it is a link; <code>external</code> opens it in a new tab and adds an arrow after the text.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>icon</code></td><td></td><td>An icon before the text (a name or a component)</td></tr><tr><td><code>href</code></td><td></td><td>Renders a link</td></tr><tr><td><code>external</code></td><td><code>false</code></td><td>A destination outside the application (with <code>href</code>)</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be pressed (not with <code>href</code>)</td></tr><tr><td><code>onclick</code></td><td></td><td>Called when pressed</td></tr><tr><td><code>children</code></td><td>required</td><td>The text</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is a control without a line or a surface: it is laid out as the text and the icons it shows, as text is, so it is measured like the text around it: its line box in a layout, trimmed at the edge of a container. The area that is pressed and the focus ring reach the control&#39;s height around it without taking room. Outside a sentence it is a block of its own, as wide as what it shows. There is no padding at the sides, so its edge lines up with the text around it. The text is blue-ink, underlined on hover. In a sentence, inside a <a href="./text">Text</a>, it takes the size and the line height of the text around it and stays on the line. Inside something that declares a height (a list item, a toolbar) the text is trimmed to its ink. Disabled, the text takes the text color, dimmed.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/link-action/" title="LinkAction" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/link-action/" target="_blank" rel="noopener">LinkAction</a></figcaption></figure>',10)])])}const m=e(n,[["render",d]]);export{u as __pageData,m as default};
